#!/usr/bin/env bash
# Question 2: ${Q2_APP} unreachable through the ingress. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl get ingressclass traefik >/dev/null 2>&1 && kubectl get gatewayclass traefik >/dev/null 2>&1 || {
  echo "this cluster image has no Traefik or Gateway API: rebuild images with ./cka images build --force" >&2
  exit 1
}
kubectl create namespace "${Q2_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q2_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q2_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q2_APP}
  namespace: ${Q2_NS}
spec:
  replicas: 2
  selector:
    matchLabels: { app: ${Q2_APP} }
  template:
    metadata:
      labels: { app: ${Q2_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ name: http, containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: http }
            periodSeconds: 5
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q2_APP}
  namespace: ${Q2_NS}
spec:
  selector: { app: ${Q2_APP} }
  ports: [{ port: 80, targetPort: http }]
---
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: ${Q2_APP}
  namespace: ${Q2_NS}
spec:
  ingressClassName: traefik
  rules:
    - host: www.${Q2_NS}.lab
      http:
        paths:
          - path: /
            pathType: Prefix
            backend:
              service: { name: ${Q2_APP}, port: { number: 80 } }
---
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
metadata:
  name: ${Q2_APP}
  namespace: ${Q2_NS}
spec:
  parentRefs:
    - { name: traefik-gateway, namespace: traefik, sectionName: web }
  hostnames: [api.${Q2_NS}.lab]
  rules:
    - backendRefs:
        - { name: ${Q2_APP}, port: 80 }
EOF
kubectl -n "${Q2_NS}" rollout status "deployment/${Q2_APP}" --timeout=240s
for _ in $(seq 1 60); do curl -s -m 5 -H "Host: www.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' && break; sleep 2; done
curl -s -m 5 -H "Host: www.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx'
for _ in $(seq 1 60); do curl -s -m 5 -H "Host: api.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' && break; sleep 2; done
curl -s -m 5 -H "Host: api.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx'

case "${Q2_FAULT}" in
  ingress-service-name)
    kubectl -n "${Q2_NS}" patch ingress "${Q2_APP}" --type=json -p '[{"op":"replace","path":"/spec/rules/0/http/paths/0/backend/service/name","value":"'"${Q2_APP}"'-svc"}]'
    ;;
  ingress-service-port)
    kubectl -n "${Q2_NS}" patch ingress "${Q2_APP}" --type=json -p '[{"op":"replace","path":"/spec/rules/0/http/paths/0/backend/service/port/number","value":8080}]'
    ;;
  ingress-class)
    kubectl -n "${Q2_NS}" patch ingress "${Q2_APP}" --type=json -p '[{"op":"replace","path":"/spec/ingressClassName","value":"nginx"}]'
    ;;
  ingress-path)
    kubectl -n "${Q2_NS}" patch ingress "${Q2_APP}" --type=json -p '[{"op":"replace","path":"/spec/rules/0/http/paths/0/path","value":"/index.html"},{"op":"replace","path":"/spec/rules/0/http/paths/0/pathType","value":"Exact"}]'
    ;;
  route-parent)
    kubectl -n "${Q2_NS}" patch httproute "${Q2_APP}" --type=json -p '[{"op":"replace","path":"/spec/parentRefs/0/name","value":"web-gateway"}]'
    ;;
  route-section)
    kubectl -n "${Q2_NS}" patch httproute "${Q2_APP}" --type=json -p '[{"op":"replace","path":"/spec/parentRefs/0/sectionName","value":"websecure"}]'
    ;;
  route-backend-port)
    kubectl -n "${Q2_NS}" patch httproute "${Q2_APP}" --type=json -p '[{"op":"replace","path":"/spec/rules/0/backendRefs/0/port","value":8080}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

case "${Q2_FAULT}" in
  ingress-service-name)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: www.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "www.${Q2_NS}.lab is still served" >&2
    exit 1
    ;;
  ingress-service-port)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: www.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "www.${Q2_NS}.lab is still served" >&2
    exit 1
    ;;
  ingress-class)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: www.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "www.${Q2_NS}.lab is still served" >&2
    exit 1
    ;;
  ingress-path)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: www.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "www.${Q2_NS}.lab is still served" >&2
    exit 1
    ;;
  route-parent)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q2_NS}.lab is still served" >&2
    exit 1
    ;;
  route-section)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q2_NS}.lab is still served" >&2
    exit 1
    ;;
  route-backend-port)
    for _ in $(seq 1 45); do
      curl -s -m 5 -H "Host: api.${Q2_NS}.lab" http://controlplane:30080/ | grep -q 'Welcome to nginx' || exit 0
      sleep 2
    done
    echo "api.${Q2_NS}.lab is still served" >&2
    exit 1
    ;;
esac
